import { z } from 'zod';

// `code` is auto-generated by the service (GV-0001, GV-0002, ...) unless the
// client supplies one explicitly — same convention as Promotion/every other
// master. `voucherName` (not `name`) is the wire/API field name deliberately
// kept domain-specific, same as Promotion's `promotionName` — the service's
// toRowData() maps it onto the Prisma column called `name`.
export const createGiftVoucherSchema = z
  .object({
    code: z.string().trim().min(1).optional(),
    voucherName: z.string().trim().min(1, 'Voucher name is required'),
    voucherType: z.enum(['Fixed Amount', 'Percentage Discount', 'Digital Gift Card', 'Physical Gift Card'], {
      errorMap: () => ({ message: 'Select a voucher type' }),
    }),
    // Coerced to a number here (never trusted as-is from the client) so
    // "10abc" or a negative value can never reach the database — the
    // frontend's own zod schema blocks these at the form too, but the
    // backend is the actual source of truth.
    voucherValue: z.coerce.number().nonnegative('Voucher value cannot be negative').default(0),
    description: z.string().trim().max(500).optional().or(z.literal('')).nullable(),
    startDate: z.coerce.date({ errorMap: () => ({ message: 'Valid From date is required' }) }),
    endDate: z.coerce.date().optional().nullable(),
    noExpiry: z.coerce.boolean().default(false),
    minimumBillAmount: z.coerce.number().nonnegative('Minimum bill amount cannot be negative').default(0),
    maximumUsage: z.enum(['no-limit', 'once', 'limited']).default('no-limit'),
    onePerCustomer: z.coerce.boolean().default(false),
    partialRedemptionAllowed: z.coerce.boolean().default(true),
    allowMultipleInOneBill: z.coerce.boolean().default(true),
    applicableTo: z.enum(['all', 'specific', 'category']).default('all'),
    isActive: z.coerce.boolean().default(true),
    sendSms: z.coerce.boolean().default(false),
    sendEmail: z.coerce.boolean().default(false),
  })
  .superRefine((values, ctx) => {
    if (!values.noExpiry && !values.endDate) {
      ctx.addIssue({ code: z.ZodIssueCode.custom, path: ['endDate'], message: 'Valid Till date is required' });
    }
    if (values.endDate && values.endDate < values.startDate) {
      ctx.addIssue({ code: z.ZodIssueCode.custom, path: ['endDate'], message: 'Valid Till date cannot be before Valid From date' });
    }
    if (values.voucherType === 'Percentage Discount' && values.voucherValue > 100) {
      ctx.addIssue({ code: z.ZodIssueCode.custom, path: ['voucherValue'], message: 'Percentage value cannot exceed 100%' });
    }
  });

// Edit mode always resubmits the whole form (see CreateGiftVoucherPage), so
// the update schema keeps the same full validation instead of `.partial()`.
export const updateGiftVoucherSchema = createGiftVoucherSchema;
